package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import org.junit.jupiter.api.Test;

/** Real native block persistence. The large pure payload is fictional and is not a native final business proof. */
class JdbcCatalogSourceFinalBlocksTest {
 GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
 CatalogSourceFinalProofTest fixture(String category)throws Exception{var f=new CatalogSourceFinalProofTest(){@Override GenerationJdbcStoreTest database(){return JdbcCatalogSourceFinalBlocksTest.this.database();}};f.install(category,true);return f;}
 FrozenCatalogSourceFinal.Encoded encoded(String category){var f=new CatalogSourceFinalResultTest();return FrozenCatalogSourceFinal.encode(f.result(f.fixture(category,501,"😀".repeat(8000),List.of())));}
 @Test void fourConfiguredCategoriesPersistEveryMultibyteBlockAndReadExactCompleteBytes()throws Exception{
  for(String category:List.of("agent","skill","workflow","model")){var f=fixture(category);var value=encoded(category);assertEquals(f.ref.ownerId(),value.reference().ownerId());assertTrue(value.payloads().size()>2);var store=new JdbcCatalogSourceFinalBlocks(f.f.source,category);String owner=value.reference().ownerId(),stamp=JdbcCatalogSourceFinalBlocks.stamp(owner,value.reference().indexHash());
   for(int n=0;n<value.payloads().size();n++){int number=n;f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,number,value.payloads().get(number),f.f.clock.instant());return true;});}var original=new CatalogSourceFinalResultTest();var result=original.result(original.fixture(category,501,"😀".repeat(8000),List.of()));var actual=f.results.readonly(()->{store.immutableOwner(owner);return store.parts(owner,stamp).stream().map(JdbcCatalogSourceFinalBlocks.Part::payload).toList();});assertEquals(value.payloads(),actual);assertEquals(result.json(),FrozenCatalogSourceFinal.decode(value.reference(),actual,result).json());assertEquals(0,f.f.count("target_type='catalog_source_final_result'"));assertEquals(0,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));
  }
 }
 @Test void nativeOwnerChangedToAnotherValidCategoryInsideWriterRollsBackWithoutBlocks()throws Exception{
  var f=fixture("agent");var store=new JdbcCatalogSourceFinalBlocks(f.f.source,"agent");var value=encoded("agent");String owner=f.ref.ownerId(),stamp=JdbcCatalogSourceFinalBlocks.stamp(owner,value.reference().indexHash());assertThrows(RuntimeException.class,()->f.prepared.tx(()->{f.f.jdbc.update("UPDATE jobs SET task_type='skill_dedup' WHERE id=?",owner);store.lockOwner(owner);store.put(owner,stamp,0,value.payloads().getFirst(),f.f.clock.instant());return true;}));assertEquals("agent_dedup",f.f.jdbc.queryForObject("SELECT task_type FROM jobs WHERE id=?",String.class,owner));assertTrue(f.results.readonly(()->store.parts(owner,stamp)).isEmpty());assertThrows(RuntimeException.class,()->f.results.readonly(()->{new JdbcCatalogSourceFinalBlocks(f.f.source,"model").immutableOwner(owner);return true;}));
 }
 @Test void interruptedNativePrefixAndRehashedStoredChangesCannotDecodeCompleteOriginal()throws Exception{
  var f=fixture("skill");var store=new JdbcCatalogSourceFinalBlocks(f.f.source,"skill");var value=encoded("skill");String owner=f.ref.ownerId(),stamp=JdbcCatalogSourceFinalBlocks.stamp(owner,value.reference().indexHash());f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,0,value.payloads().getFirst(),f.f.clock.instant());return true;});var pure=new CatalogSourceFinalResultTest();var result=pure.result(pure.fixture("skill",501,"😀".repeat(8000),List.of()));assertThrows(RuntimeException.class,()->FrozenCatalogSourceFinal.decode(value.reference(),f.results.readonly(()->store.parts(owner,stamp).stream().map(JdbcCatalogSourceFinalBlocks.Part::payload).toList()),result));
  var chunk=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("schema_version","catalog-source-final-chunk-v1").put("bytes_base64",Base64.getEncoder().encodeToString("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8)));String body=JdbcFrozenInputs.canonical(chunk);f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,1,body,f.f.clock.instant());return true;});assertThrows(RuntimeException.class,()->FrozenCatalogSourceFinal.decode(value.reference(),f.results.readonly(()->store.parts(owner,stamp).stream().map(JdbcCatalogSourceFinalBlocks.Part::payload).toList()),result));assertEquals(0,f.f.count("target_type='catalog_source_final_result'"));
 }
 @Test void sqlBoundsHashesNativeRolesAndRowGapsRemainMandatory()throws Exception{
  var f=fixture("workflow");var store=new JdbcCatalogSourceFinalBlocks(f.f.source,"workflow");var value=encoded("workflow");String owner=f.ref.ownerId(),stamp=JdbcCatalogSourceFinalBlocks.stamp(owner,value.reference().indexHash());f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,0,value.payloads().getFirst(),f.f.clock.instant());return true;});String id=JdbcCatalogSourceFinalBlocks.partId(owner,stamp,0);f.f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE id=?",new byte[32],id);assertThrows(RuntimeException.class,()->f.results.readonly(()->store.part(owner,stamp,0)));f.f.jdbc.update("UPDATE jobs SET payload_hash=?,payload_json=? WHERE id=?",HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.INPUT_PART,CanonicalJson.parse(value.payloads().getFirst()))),"{\"fictional\":\""+"x".repeat(262145)+"\"}",id);assertThrows(RuntimeException.class,()->f.results.readonly(()->store.part(owner,stamp,0)));
  f.f.jdbc.update("DELETE FROM jobs WHERE id=?",id);f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,1,value.payloads().get(1),f.f.clock.instant());return true;});assertThrows(RuntimeException.class,()->f.results.readonly(()->store.parts(owner,stamp)));
 }
 @Test void constructorsAndTransactionsCannotGrantStorageAuthority()throws Exception{
  var source=org.mockito.Mockito.mock(javax.sql.DataSource.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new JdbcCatalogSourceFinalBlocks(source,category));for(String category:List.of("news_tech","AGENT","agent_dedup",""))assertThrows(RuntimeException.class,()->new JdbcCatalogSourceFinalBlocks(source,category));org.mockito.Mockito.verifyNoInteractions(source);var f=fixture("model");var store=new JdbcCatalogSourceFinalBlocks(f.f.source,"model");var value=encoded("model");String owner=f.ref.ownerId(),stamp=JdbcCatalogSourceFinalBlocks.stamp(owner,value.reference().indexHash());assertThrows(RuntimeException.class,()->store.parts(owner,stamp));assertThrows(RuntimeException.class,()->f.results.readonly(()->{store.lockOwner(owner);return true;}));assertThrows(RuntimeException.class,()->f.results.readonly(()->{store.put(owner,stamp,0,value.payloads().getFirst(),f.f.clock.instant());return true;}));assertThrows(RuntimeException.class,()->f.prepared.tx(()->{store.lockOwner(owner);store.put(owner,stamp,129,value.payloads().getFirst(),f.f.clock.instant());return true;}));
 }
}
